    "explanation": "Doğru Seçenek: A) Denge durumunda olan izole bir sistemin entropisi minimum değerdedir. Soru kökünde Biyofizik kapsamında yer alan bilgilerden yanlış/istisna olan ifade sorulmaktadır. A seçeneğinde belirtilen 'Denge durumunda olan izole bir sistemin entropisi minimum değerdedir' ifadesi bilimsel olarak geçersizdir (yanlıştır) ve bu konudaki kurala/mekanizmaya uymaz; dolayısıyla doğru cevap olarak seçilmelidir. Buna karşılık diğer çeldirici seçeneklerde sunulan (B) 'Termodinamiğin 2. Kanununa göre izole bir sistemde kendiliğinden gerçekleşen süreçlerde toplam entropi sürekli artar'; C) 'Termodinamiğin 1. Kanunu enerjinin korunduğunu, yoktan var veya vardan yok edilemeyeceğini belirtir'; D) 'Gibbs serbest enerjisindeki değişim (ΔG) negatif olan reaksiyonlar ekzergoniktir ve kendiliğinden gerçekleşir'; E) 'Canlı hücreler açık termodinamik sistemler olup çevreleriyle madde ve enerji alışverişi yaparlar') ifadeleri ise Biyofizik literatüründe doğru, geçerli ve beklenen bilimsel bilgilerdir. Sınavda sıklıkla yapılan hata bu doğru önermeleri görüp işaretlemektir; ancak soru 'yanlış / istisna' olanı sorguladığından çeldiriciler elenir.",
